const charactersBeforeBackground=characters;
characters=function(){const c=data.characters[ci];if(c){if(typeof c.nonWhiteBackground!=='boolean')c.nonWhiteBackground=false;if(c.multiPrompt?.startsWith('以已确认的正面图为唯一角色身份参考')){c.multiPrompt='保持参考图中同一个角色的外形、比例、材质和服装。';}}charactersBeforeBackground();if(!c)return;const generate=document.querySelector('#generate');if(!generate)return;const group=document.createElement('div');group.style.cssText='padding:12px 0;border-top:1px solid var(--line);margin-top:8px';const label=document.createElement('label');label.style.cssText='display:flex;align-items:center;gap:8px;font-size:12px;color:var(--ink);margin-bottom:7px';const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.id='nonWhiteBackground';checkbox.checked=c.nonWhiteBackground;checkbox.style.cssText='display:inline-block;width:auto;margin:0';label.append(checkbox,document.createTextNode('非白背景（中灰色）'));const hint=document.createElement('p');hint.className='subtle';const update=()=>{hint.textContent=c.nonWhiteBackground?'当前选择：中灰背景，用于后续角色视图和合成。':'当前：默认纯白背景。也可手动勾选中灰背景；修改仅影响后续生成。';};checkbox.onchange=()=>{c.nonWhiteBackground=checkbox.checked;save();update()};update();group.append(label,hint);generate.before(group);};render();
